import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_map/flutter_map.dart';import 'package:geolocator/geolocator.dart';import 'package:latlong2/latlong.dart';import 'package:provider/provider.dart';import '../../data/bus_route.dart';import '../../data/bus_station.dart';import '../../utils/static.dart';import '../../widgets/editor/editor_side_panel.dart';import '../../widgets/editor/map_controls.dart';import '../../widgets/editor/map_view_section.dart';import '../../widgets/editor/source_sidebar.dart';import '../../widgets/editor/station_dialog.dart';import '../widgets/editor/route_editor_controller.dart';class RouteEditorPage extends StatefulWidget {  final BusRoute? initialRoute;  const RouteEditorPage({super.key, this.initialRoute});  @override  State<RouteEditorPage> createState() => _RouteEditorPageState();}class _RouteEditorPageState extends State<RouteEditorPage> {  late RouteEditorController _ctrl;  @override  void initState() {    super.initState();    _ctrl = RouteEditorController(initialRoute: widget.initialRoute);    WidgetsBinding.instance.addPostFrameCallback((_) => _recenterMap());  }  void _recenterMap() {    final List<LatLng> pts = [      ..._ctrl.goPath,      ..._ctrl.backPath,      ..._ctrl.goStations.map((s) => LatLng(s.lat, s.lon)),      ..._ctrl.backStations.map((s) => LatLng(s.lat, s.lon)),    ].where((p) => p.latitude != 0 && p.longitude != 0).toList();    if (pts.isEmpty) {      _ctrl.mapController.move(const LatLng(24.9892, 121.3135), 16);    } else {      _ctrl.mapController.fitCamera(        CameraFit.bounds(          bounds: LatLngBounds.fromPoints(pts),          padding: const EdgeInsets.all(50),        ),      );    }  }  Future<void> _onMapStationTap(LatLng p, {BusStation? existing}) async {    final list = _ctrl.isEditingGo ? _ctrl.goStations : _ctrl.backStations;    final other = _ctrl.isEditingGo ? _ctrl.backStations : _ctrl.goStations;    final List<SourceStationGroup> candidates = [];    const double threshold = 3.0;    for (var s in list) {      if (Geolocator.distanceBetween(p.latitude, p.longitude, s.lat, s.lon) <=          threshold) {        candidates.add(          SourceStationGroup(station: s, source: "current", routeNames: []),        );      }    }    for (var s in other) {      if (Geolocator.distanceBetween(p.latitude, p.longitude, s.lat, s.lon) <=          threshold) {        candidates.add(          SourceStationGroup(station: s, source: "other_side", routeNames: []),        );      }    }    for (var g in _ctrl.nearbySourceGroups) {      if (Geolocator.distanceBetween(            p.latitude,            p.longitude,            g.station.lat,            g.station.lon,          ) <=          threshold) {        if (!candidates.any(          (c) => c.locationKey == g.locationKey && c.source == g.source,        )) {          candidates.add(g);        }      }    }    SourceStationGroup? selected;    if (candidates.length > 1) {      selected = await showDialog<SourceStationGroup>(        context: context,        builder: (ctx) => AlertDialog(          title: const Text(            "選擇站點",            style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold),          ),          content: SizedBox(            width: 300,            child: ListView.builder(              shrinkWrap: true,              itemCount: candidates.length,              itemBuilder: (c, i) {                final g = candidates[i];                final bool inCurrent = g.source == "current";                final bool inOther = g.source == "other_side";                String subtitle = "";                if (inCurrent) {                  subtitle = "已在路徑中 (第 ${list.indexOf(g.station) + 1} 站)";                } else if (inOther) {                  subtitle = "不可修改，請切換方向";                } else {                  List<String> routes = g.routeNames;                  if (routes.length > 5)                    routes = routes.take(5).toList()..add("...");                  subtitle =                      "路線：${(routes.isEmpty ? "自定義站點" : routes.join(', '))}";                }                return ListTile(                  dense: true,                  title: Text(                    g.station.name,                    style: const TextStyle(                      fontSize: 12,                      fontWeight: FontWeight.bold,                    ),                  ),                  subtitle: Text(                    subtitle,                    style: TextStyle(                      fontSize: 10,                      color: inCurrent                          ? Colors.orange                          : (inOther ? Colors.redAccent : Colors.grey),                    ),                  ),                  onTap: inOther ? null : () => Navigator.pop(ctx, g),                );              },            ),          ),        ),      );      if (selected == null) return;    } else if (candidates.length == 1) {      if (candidates.first.source == "other_side") return;      selected = candidates.first;    }    if (selected == null && existing == null) {      final res = await showDialog<Map<String, dynamic>>(        context: context,        builder: (ctx) => StationDialog(point: p, currentList: list),      );      if (res != null && res['action'] == 'save') {        setState(() {          list.insert(            ((res['order'] as int) - 1).clamp(0, list.length),            res['station'],          );          _ctrl.syncStationOrders();          _ctrl.isMapTapMode = false;          _ctrl.markDirty();        });      }      return;    }    final target = selected?.station ?? existing;    if (target != null) {      List<String> displayRoutes = selected?.routeNames ?? [];      if (displayRoutes.length > 5)        displayRoutes = displayRoutes.take(5).toList()..add("...");      final res = await showDialog<Map<String, dynamic>>(        context: context,        builder: (ctx) => StationDialog(          point: LatLng(target.lat, target.lon),          existing: target,          currentList: list,          routeNames: displayRoutes,        ),      );      if (res == null) return;      setState(() {        if (res['action'] == 'delete') {          list.remove(target);        } else if (res['action'] == 'move') {          _ctrl.movingStationIndex = list.indexOf(target);        } else if (res['action'] == 'save') {          if (list.contains(target)) list.remove(target);          list.insert(            ((res['order'] as int) - 1).clamp(0, list.length),            res['station'],          );        }        _ctrl.syncStationOrders();        _ctrl.isMapTapMode = false;        _ctrl.markDirty();      });    }  }  Future<void> _onPathNodeTap(int idx) async {    if (_ctrl.pathAddMode != PathAddMode.none) return;    final res = await showDialog<String>(      context: context,      builder: (ctx) => AlertDialog(        title: Text("節點 #${idx + 1}"),        actions: [          TextButton(            onPressed: () => Navigator.pop(ctx, "delete"),            child: const Text("刪除", style: TextStyle(color: Colors.red)),          ),          TextButton(            onPressed: () => Navigator.pop(ctx, "move"),            child: const Text("移動"),          ),          TextButton(            onPressed: () => Navigator.pop(ctx),            child: const Text("關閉"),          ),        ],      ),    );    if (res == "delete") {      final p = List<LatLng>.from(        _ctrl.isEditingGo ? _ctrl.goPath : _ctrl.backPath,      )..removeAt(idx);      if (_ctrl.isEditingGo)        _ctrl.wktGoCtrl.text = _ctrl.generateWkt(p);      else        _ctrl.wktBackCtrl.text = _ctrl.generateWkt(p);      _ctrl.syncPaths();      _ctrl.markDirty();    } else if (res == "move") {      setState(() => _ctrl.movingPathIndex = idx);    }  }  @override  Widget build(BuildContext context) {    return ChangeNotifierProvider.value(      value: _ctrl,      child: Consumer<RouteEditorController>(        builder: (context, ctrl, _) {          bool isMoving =              ctrl.movingStationIndex != null || ctrl.movingPathIndex != null;          bool showCenter =              ctrl.isMapTapMode ||              ctrl.pathAddMode == PathAddMode.end ||              isMoving;          return PopScope(            canPop: !ctrl.isDirty,            onPopInvokedWithResult: (didPop, r) async {              if (didPop) return;              final leave = await showDialog<bool>(                context: context,                builder: (ctx) => AlertDialog(                  title: const Text("尚未儲存"),                  content: const Text("確定要離開嗎？"),                  actions: [                    TextButton(                      onPressed: () => Navigator.pop(ctx, false),                      child: const Text("取消"),                    ),                    TextButton(                      onPressed: () => Navigator.pop(ctx, true),                      child: const Text(                        "離開",                        style: TextStyle(color: Colors.red),                      ),                    ),                  ],                ),              );              if (leave == true) Navigator.of(context).pop();            },            child: Theme(              data: ThemeData.dark(),              child: Scaffold(                appBar: AppBar(                  toolbarHeight: 40,                  title: const Text("路線編輯", style: TextStyle(fontSize: 14)),                  actions: [                    TextButton.icon(                      onPressed: () {                        if (ctrl.isJsonMode) {                          try {                            final data = jsonDecode(ctrl.jsonCtrl.text);                            final nr = BusRoute.fromJson(data);                            setState(() {                              ctrl.idCtrl.text = nr.id;                              ctrl.nameCtrl.text = nr.name;                              ctrl.descCtrl.text = nr.description;                              ctrl.depCtrl.text = nr.departure;                              ctrl.destCtrl.text = nr.destination;                              ctrl.wktGoCtrl.text = nr.path.go;                              ctrl.wktBackCtrl.text = nr.path.back;                              ctrl.goStations = List.from(nr.stations.go);                              ctrl.backStations = List.from(nr.stations.back);                              ctrl.isJsonMode = false;                            });                            ctrl.syncStationOrders();                            ctrl.syncPaths();                          } catch (e) {                            showDialog(                              context: context,                              builder: (ctx) => AlertDialog(                                title: const Text("JSON 錯誤"),                                content: Text(e.toString()),                              ),                            );                          }                        } else {                          ctrl.jsonCtrl.text = const JsonEncoder.withIndent(                            '  ',                          ).convert(ctrl.prepareRouteData().toJson());                          setState(() => ctrl.isJsonMode = true);                        }                      },                      icon: Icon(ctrl.isJsonMode ? Icons.map : Icons.code),                      label: Text(ctrl.isJsonMode ? "視覺編輯" : "JSON"),                    ),                    const SizedBox(width: 8),                    FilledButton.icon(                      onPressed: () async {                        await Static.saveCustomRoute(                          ctrl.prepareRouteData(),                          oldId: widget.initialRoute?.id,                        );                        setState(() => ctrl.isDirty = false);                        if (mounted) Navigator.pop(context, true);                      },                      icon: const Icon(Icons.save, size: 16),                      label: const Text("儲存"),                    ),                    const SizedBox(width: 8),                  ],                ),                body: ctrl.isJsonMode                    ? _buildJson(ctrl)                    : _buildGui(ctrl, isMoving, showCenter),              ),            ),          );        },      ),    );  }  Widget _buildGui(    RouteEditorController ctrl,    bool isMoving,    bool showCenter,  ) => Row(    children: [      EditorSidePanel(        idCtrl: ctrl.idCtrl,        nameCtrl: ctrl.nameCtrl,        descCtrl: ctrl.descCtrl,        depCtrl: ctrl.depCtrl,        destCtrl: ctrl.destCtrl,        wktCtrl: ctrl.isEditingGo ? ctrl.wktGoCtrl : ctrl.wktBackCtrl,        isEditingGo: ctrl.isEditingGo,        autoWkt: false,        isPathEditing: ctrl.isPathEditing,        stations: ctrl.isEditingGo ? ctrl.goStations : ctrl.backStations,        pathPoints: ctrl.isEditingGo ? ctrl.goPath : ctrl.backPath,        onDirectionChanged: (v) => setState(() => ctrl.isEditingGo = v),        onAutoWktChanged: (v) {},        onWktManualChanged: ctrl.syncPaths,        onTogglePathEdit: () => setState(() {          ctrl.isPathEditing = !ctrl.isPathEditing;          ctrl.isMapTapMode = false;          ctrl.pathAddMode = PathAddMode.none;        }),        onReorder: (o, n) {          setState(() {            final l = ctrl.isEditingGo ? ctrl.goStations : ctrl.backStations;            if (n > o) n -= 1;            l.insert(n, l.removeAt(o));            ctrl.syncStationOrders();            ctrl.markDirty();          });        },        onStationRemove: (i) => _onMapStationTap(          LatLng(0, 0),          existing: (ctrl.isEditingGo ? ctrl.goStations : ctrl.backStations)[i],        ),        onStationTap: (i, s) =>            _onMapStationTap(LatLng(s.lat, s.lon), existing: s),        onPathPointTap: (idx) => _onPathNodeTap(idx),      ),      const VerticalDivider(width: 1),      Expanded(        child: Stack(          children: [            MapViewSection(              mapController: ctrl.mapController,              goPath: ctrl.goPath,              pathAddMode: ctrl.pathAddMode,              backPath: ctrl.backPath,              isEditingGo: ctrl.isEditingGo,              brightness: ctrl.brightness,              currentZoom: ctrl.currentZoom,              nearbySourceStations: ctrl.nearbySourceGroups                  .map((g) => g.station)                  .toList(),              goStations: ctrl.goStations,              backStations: ctrl.backStations,              isMapTapMode: showCenter,              isPathEditing: ctrl.isPathEditing,              movingStationIndex: ctrl.movingStationIndex,              movingPathIndex: ctrl.movingPathIndex,              previewPoint: showCenter ? ctrl.previewPoint : null,              onPositionChanged: ctrl.onPositionChanged,              onMapTap: (p) {                if (ctrl.isPathEditing &&                    ctrl.pathAddMode == PathAddMode.intermediate) {                  final pList = List<LatLng>.from(                    ctrl.isEditingGo ? ctrl.goPath : ctrl.backPath,                  );                  int idx = ctrl.getInsertIndex(p, pList);                  if (idx != -1) {                    setState(() {                      pList.insert(idx, p);                      if (ctrl.isEditingGo)                        ctrl.wktGoCtrl.text = ctrl.generateWkt(pList);                      else                        ctrl.wktBackCtrl.text = ctrl.generateWkt(pList);                      ctrl.markDirty();                    });                    ctrl.syncPaths();                  }                }              },              onMarkerTap: (p, s) {                if (!showCenter && !isMoving) _onMapStationTap(p, existing: s);              },              onPathPointTap: (idx) {                if (!showCenter && !isMoving) _onPathNodeTap(idx);              },            ),            Positioned(              bottom: 20,              right: 85,              child: MapControls(                isFabMenuExpanded: ctrl.isFabMenuExpanded,                brightness: ctrl.brightness,                onToggleFab: () => setState(                  () => ctrl.isFabMenuExpanded = !ctrl.isFabMenuExpanded,                ),                onRecenter: _recenterMap,                onBrightnessChanged: (v) => setState(() => ctrl.brightness = v),              ),            ),            SourceSidebar(              selectedSources: ctrl.selectedSources,              onSourceToggle: (key) {                setState(() {                  if (ctrl.selectedSources.contains(key))                    ctrl.selectedSources.remove(key);                  else                    ctrl.selectedSources.add(key);                });                ctrl.loadSourceStations();              },            ),            Positioned(              bottom: 20,              left: 20,              child: Row(                children: [                  if (showCenter)                    FilledButton.icon(                      onPressed: () {                        setState(() {                          if (isMoving) {                            ctrl.movingStationIndex = null;                            ctrl.movingPathIndex = null;                          } else if (ctrl.isMapTapMode ||                              ctrl.pathAddMode == PathAddMode.end) {                            final pos = ctrl.mapController.camera.center;                            if (ctrl.isPathEditing &&                                ctrl.pathAddMode == PathAddMode.end) {                              final pList = List<LatLng>.from(                                ctrl.isEditingGo ? ctrl.goPath : ctrl.backPath,                              )..add(pos);                              if (ctrl.isEditingGo)                                ctrl.wktGoCtrl.text = ctrl.generateWkt(pList);                              else                                ctrl.wktBackCtrl.text = ctrl.generateWkt(pList);                            } else if (!ctrl.isPathEditing &&                                ctrl.isMapTapMode) {                              _onMapStationTap(pos);                              ctrl.isMapTapMode = false;                            }                          }                          ctrl.markDirty();                        });                        ctrl.syncPaths();                      },                      icon: const Icon(Icons.check),                      label: Text(isMoving ? "確認移動" : "確認新增"),                      style: FilledButton.styleFrom(                        backgroundColor: Colors.green,                      ),                    ),                  const SizedBox(width: 8),                  if (!showCenter && ctrl.pathAddMode == PathAddMode.none) ...[                    if (ctrl.isPathEditing) ...[                      FilledButton.icon(                        onPressed: () => setState(                          () => ctrl.pathAddMode = PathAddMode.intermediate,                        ),                        icon: const Icon(Icons.add_road),                        label: const Text("中間節點"),                      ),                      const SizedBox(width: 8),                      FilledButton.icon(                        onPressed: () =>                            setState(() => ctrl.pathAddMode = PathAddMode.end),                        icon: const Icon(Icons.polyline),                        label: const Text("末端節點"),                      ),                    ] else                      FilledButton.icon(                        onPressed: () =>                            setState(() => ctrl.isMapTapMode = true),                        icon: const Icon(Icons.add_location),                        label: const Text("新增站點"),                      ),                  ],                  if (showCenter || ctrl.pathAddMode != PathAddMode.none) ...[                    const SizedBox(width: 8),                    FilledButton.icon(                      onPressed: () => setState(() {                        ctrl.isMapTapMode = false;                        ctrl.pathAddMode = PathAddMode.none;                        ctrl.movingStationIndex = null;                        ctrl.movingPathIndex = null;                      }),                      icon: const Icon(Icons.close),                      label: const Text("取消"),                      style: FilledButton.styleFrom(                        backgroundColor: Colors.red,                      ),                    ),                  ],                ],              ),            ),          ],        ),      ),    ],  );  Widget _buildJson(RouteEditorController ctrl) => Padding(    padding: const EdgeInsets.all(12),    child: TextField(      controller: ctrl.jsonCtrl,      maxLines: null,      expands: true,      style: const TextStyle(fontFamily: 'monospace', fontSize: 11),      decoration: const InputDecoration(        border: OutlineInputBorder(),        hintText: "貼上 JSON...",      ),    ),  );}